1	package vault
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/base64"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"sort"
13	)
14	
15	// Package format:
16	//
17	// A snapshot package is an indented JSON document that moves one complete
18	// snapshot, together with whatever content objects it needs, between
19	// repositories. A full package carries every referenced object; an
20	// incremental package records a Base and only carries objects the base
21	// snapshot does not reference. Either way Snapshot always holds the complete
22	// target mapping — additions, overwrites, and deletions relative to the base
23	// are expressed solely by that mapping.
24	//
25	//	{
26	//	  "format": "artifact-vault-snapshot",
27	//	  "version": 1,
28	//	  "snapshot": { "name": "...", "entries": { ... } },
29	//	  "base": { "name": "...", "entries": { ... } },     // delta only, optional
30	//	  "objects": [
31	//	    { "digest": "<sha256 hex>", "size": 123, "data": "<base64>" }
32	//	  ]
33	//	}
34	//
35	// An object's SHA-256 digest over its decoded bytes is also its filename
36	// inside objects/, so no package record can name a destination outside that
37	// directory.
38	const (
39		packageFormat  = "artifact-vault-snapshot"
40		packageVersion = 1
41	)
42	
43	// PackageObject is one content object carried by a package.
44	type PackageObject struct {
45		Digest string `json:"digest"`
46		Size   int64  `json:"size"`
47		Data   string `json:"data"`
48	}
49	
50	// Package is the on-disk snapshot transfer format.
51	type Package struct {
52		Format   string          `json:"format"`
53		Version  int             `json:"version"`
54		Snapshot Snapshot        `json:"snapshot"`
55		Base     *Snapshot       `json:"base,omitempty"`
56		Objects  []PackageObject `json:"objects"`
57	}
58	
59	// rejectDuplicateKeys walks the raw JSON token stream and fails if any object
60	// lists the same key twice. encoding/json otherwise keeps only the last
61	// occurrence, which could hide a duplicate object or entry behind an earlier,
62	// validated one.
63	func rejectDuplicateKeys(data []byte) error {
64		type frame struct {
65			object    bool
66			keys      map[string]struct{}
67			expectKey bool
68		}
69		dec := json.NewDecoder(bytes.NewReader(data))
70		var stack []frame
71		for {
72			tok, err := dec.Token()
73			if err == io.EOF {
74				return nil
75			}
76			if err != nil {
77				return err
78			}
79			switch t := tok.(type) {
80			case json.Delim:
81				switch t {
82				case '{':
83					stack = append(stack, frame{object: true, keys: map[string]struct{}{}, expectKey: true})
84				case '[':
85					stack = append(stack, frame{object: false})
86				case '}', ']':
87					if len(stack) == 0 {
88						return errors.New("unbalanced JSON delimiters")
89					}
90					stack = stack[:len(stack)-1]
91					// The composite value just consumed completes an entry in the
92					// enclosing object, so its next string is another key.
93					if len(stack) > 0 && stack[len(stack)-1].object {
94						stack[len(stack)-1].expectKey = true
95					}
96				}
97			case string:
98				if len(stack) > 0 && stack[len(stack)-1].object {
99					f := &stack[len(stack)-1]
100					if f.expectKey {
101						if _, dup := f.keys[t]; dup {
102							return fmt.Errorf("duplicate key %q", t)
103						}
104						f.keys[t] = struct{}{}
105						f.expectKey = false
106					} else {
107						f.expectKey = true
108					}
109				}
110			default:
111				// Primitive value in an object frame: the next string token is a key.
112				if len(stack) > 0 && stack[len(stack)-1].object {
113					stack[len(stack)-1].expectKey = true
114				}
115			}
116		}
117	}
118	
119	// marshalPackage serializes the package as indented JSON. Export no longer
120	// assembles packages in memory — it streams the same document — so this is
121	// the reference serialization tests compare the streamed output against.
122	func marshalPackage(pkg *Package) ([]byte, error) {
123		data, err := json.MarshalIndent(pkg, "", "  ")
124		if err != nil {
125			return nil, err
126		}
127		return append(data, '\n'), nil
128	}
129	
130	// decodePackage parses a package without touching any repository. It enforces
131	// every self-contained invariant the specification places on a package:
132	//
133	//   - known format and version;
134	//   - snapshot (and base, if present) records are complete and valid:
135	//     snapshot name legal, entries keyed by their recorded name, legal names,
136	//     64 lowercase-hex digests, non-negative sizes;
137	//   - every object digest is valid and unique, the base64 data decodes, and
138	//     its length and SHA-256 match the record;
139	//   - the object set carries exactly the objects required by the snapshot
140	//     mapping minus the base mapping (all of them for a full package),
141	//     neither omitting a referenced digest nor carrying an unreferenced one;
142	//   - every target entry records the exact byte count of the content its
143	//     digest identifies when that content is carried: an entry keeping a valid
144	//     digest but declaring another size is a corrupt record, even though the
145	//     object record itself is intact.
146	//
147	// Sizes for objects a delta omits cannot be checked until the package meets a
148	// matching, healthy base in the destination; import performs that check before
149	// anything is written. Other cross-repository checks (an existing base
150	// snapshot, objects already present in the destination, name collisions) are
151	// likewise performed later by import, which has the destination in hand.
152	func decodePackage(data []byte) (*Package, error) {
153		// encoding/json silently keeps the last value when an object lists a key
154		// twice; that would let a package hide a duplicate entry or overwrite a
155		// structural field. Reject any such document before decoding it.
156		if err := rejectDuplicateKeys(data); err != nil {
157			return nil, fmt.Errorf("invalid package: %w", err)
158		}
159		dec := json.NewDecoder(bytes.NewReader(data))
160		dec.DisallowUnknownFields()
161		var raw struct {
162			Format   string             `json:"format"`
163			Version  int                `json:"version"`
164			Snapshot Snapshot           `json:"snapshot"`
165			Base     *Snapshot          `json:"base,omitempty"`
166			Objects  *[]json.RawMessage `json:"objects"`
167		}
168		if err := dec.Decode(&raw); err != nil {
169			return nil, fmt.Errorf("invalid package: %w", err)
170		}
171		if tok, err := dec.Token(); err != io.EOF {
172			if err == nil {
173				return nil, fmt.Errorf("invalid package: unexpected trailing content after top-level value (%v)", tok)
174			}
175			return nil, fmt.Errorf("invalid package: %w", err)
176		}
177		if raw.Format != packageFormat {
178			return nil, fmt.Errorf("invalid package: unknown format %q", raw.Format)
179		}
180		if raw.Version != packageVersion {
181			return nil, fmt.Errorf("invalid package: unsupported version %d (supported: %d)", raw.Version, packageVersion)
182		}
183		if raw.Objects == nil {
184			return nil, errors.New("invalid package: missing objects array")
185		}
186	
187		pkg := &Package{Format: raw.Format, Version: raw.Version, Objects: []PackageObject{}}
188		if err := validateSnapshotRecord("snapshot", raw.Snapshot); err != nil {
189			return nil, err
190		}
191		pkg.Snapshot = raw.Snapshot
192		if raw.Base != nil {
193			if err := validateSnapshotRecord("base", *raw.Base); err != nil {
194				return nil, err
195			}
196			pkg.Base = raw.Base
197		}
198	
199		seen := map[string]struct{}{}
200		for i, item := range *raw.Objects {
201			var obj PackageObject
202			odec := json.NewDecoder(bytes.NewReader(item))
203			odec.DisallowUnknownFields()
204			if err := odec.Decode(&obj); err != nil {
205				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
206			}
207			if _, err := odec.Token(); err != io.EOF {
208				if err == nil {
209					return nil, fmt.Errorf("invalid package: object %d: trailing content", i)
210				}
211				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
212			}
213			if !isDigest(obj.Digest) {
214				return nil, fmt.Errorf("invalid package: object %d: digest %q is not 64 lowercase hex characters", i, obj.Digest)
215			}
216			if obj.Size < 0 {
217				return nil, fmt.Errorf("invalid package: object %s has negative size %d", obj.Digest, obj.Size)
218			}
219			if _, dup := seen[obj.Digest]; dup {
220				return nil, fmt.Errorf("invalid package: duplicate object %s", obj.Digest)
221			}
222			seen[obj.Digest] = struct{}{}
223			content, err := base64.StdEncoding.DecodeString(obj.Data)
224			if err != nil {
225				return nil, fmt.Errorf("invalid package: object %s: data is not valid base64: %w", obj.Digest, err)
226			}
227			if int64(len(content)) != obj.Size {
228				return nil, fmt.Errorf("invalid package: object %s: data is %d bytes, record says %d", obj.Digest, len(content), obj.Size)
229			}
230			sum := sha256.Sum256(content)
231			if actual := hex.EncodeToString(sum[:]); actual != obj.Digest {
232				return nil, fmt.Errorf("invalid package: object %s: content checksum is %s", obj.Digest, actual)
233			}
234			pkg.Objects = append(pkg.Objects, obj)
235		}
236	
237		needed := digestsReferenced(pkg.Snapshot.Entries)
238		if pkg.Base != nil {
239			for digest := range digestsReferenced(pkg.Base.Entries) {
240				delete(needed, digest)
241			}
242		}
243		carried := map[string]int64{}
244		for _, obj := range pkg.Objects {
245			carried[obj.Digest] = obj.Size
246		}
247		for digest := range needed {
248			if _, ok := carried[digest]; !ok {
249				return nil, fmt.Errorf("invalid package: required object %s is missing from the package", digest)
250			}
251		}
252		for digest := range carried {
253			if _, ok := needed[digest]; !ok {
254				return nil, fmt.Errorf("invalid package: object %s is not referenced by the target mapping", digest)
255			}
256		}
257		// Every target entry whose content the package carries must record the
258		// carried content's exact byte count. The object's own record was already
259		// proven to match its payload above, so an entry size that disagrees is a
260		// corrupt snapshot record rather than corrupt content. Each name is
261		// checked separately: one digest may be referenced by several entries, and
262		// all of them must agree. Objects a delta omits are checked later against
263		// the destination by import. Entries are visited in name order so the
264		// first reported artifact is deterministic.
265		for _, key := range sortedEntryNames(pkg.Snapshot.Entries) {
266			entry := pkg.Snapshot.Entries[key]
267			actual, isCarried := carried[entry.Digest]
268			if isCarried && entry.Size != actual {
269				return nil, fmt.Errorf("invalid package: %w", newEntrySizeMismatchError(pkg.Snapshot.Name, entry.Name, entry.Digest, entry.Size, actual))
270			}
271		}
272		return pkg, nil
273	}
274	
275	// sortedEntryNames returns a snapshot's entry keys in sorted order, so checks
276	// that may report one of several entries name a deterministic artifact.
277	func sortedEntryNames(entries map[string]Entry) []string {
278		names := make([]string, 0, len(entries))
279		for name := range entries {
280			names = append(names, name)
281		}
282		sort.Strings(names)
283		return names
284	}
285	
286	// entrySizeMismatchError reports a target snapshot entry whose recorded size
287	// disagrees with the actual byte count of the content its digest identifies.
288	// The digest matches healthy content, so this is record corruption — distinct
289	// from a checksum failure or missing content — and the fields name everything
290	// a user needs to tell them apart.
291	type entrySizeMismatchError struct {
292		snapshot string
293		artifact string
294		digest   string
295		recorded int64
296		actual   int64
297	}
298	
299	func newEntrySizeMismatchError(snapshot, artifact, digest string, recorded, actual int64) error {
300		return entrySizeMismatchError{snapshot: snapshot, artifact: artifact, digest: digest, recorded: recorded, actual: actual}
301	}
302	
303	func (e entrySizeMismatchError) Error() string {
304		return fmt.Sprintf("snapshot %q entry %q references content %s but records size %d; the content is %d bytes",
305			e.snapshot, e.artifact, e.digest, e.recorded, e.actual)
306	}
307	
308	// validateSnapshotRecord validates one embedded snapshot the same way restore
309	// and gc validate on-disk snapshots.
310	func validateSnapshotRecord(scope string, snap Snapshot) error {
311		if err := validateName(snap.Name); err != nil {
312			return fmt.Errorf("invalid package: %s snapshot name %q is not a legal snapshot name", scope, snap.Name)
313		}
314		if snap.Entries == nil {
315			return fmt.Errorf("invalid package: %s snapshot %q is missing its entries mapping", scope, snap.Name)
316		}
317		for key, entry := range snap.Entries {
318			if err := validateEntryRecord(key, entry); err != nil {
319				return fmt.Errorf("invalid package: %s snapshot %q: %w", scope, snap.Name, err)
320			}
321		}
322		return nil
323	}
324	
325	// digestsReferenced returns the set of object digests referenced by a set of
326	// snapshot entries. Multiple entries may share one digest.
327	func digestsReferenced(entries map[string]Entry) map[string]struct{} {
328		digests := make(map[string]struct{}, len(entries))
329		for _, entry := range entries {
330			digests[entry.Digest] = struct{}{}
331		}
332		return digests
333	}
334	
335	// objectContent is a decoded package object kept in memory during import.
336	type objectContent struct {
337		digest  string
338		size    int64
339		content []byte
340	}
341	
342	// materialize decodes the base64 payloads of every carried object into
343	// memory. Import holds the objects while it stages them; packages are
344	// bounded artifacts meant to be copied between machines.
345	func (p *Package) materialize() ([]objectContent, error) {
346		objects := make([]objectContent, 0, len(p.Objects))
347		// Sort so staging order (and any error message) is deterministic.
348		ordered := append([]PackageObject(nil), p.Objects...)
349		sort.Slice(ordered, func(i, j int) bool { return ordered[i].Digest < ordered[j].Digest })
350		for _, obj := range ordered {
351			content, err := base64.StdEncoding.DecodeString(obj.Data)
352			if err != nil {
353				return nil, fmt.Errorf("object %s: %w", obj.Digest, err)
354			}
355			objects = append(objects, objectContent{digest: obj.Digest, size: obj.Size, content: content})
356		}
357		return objects, nil
358	}
