```go
// rejectEntriesCaseVariants fails when the top-level object carries a field
// whose name differs from "entries" only by letter case ("Entries",
// "ENTRIES", ...). encoding/json matches struct tags case-insensitively, so
// such a field would silently populate — or, appearing alongside the real
// entries mapping, overwrite — the name mapping. Field names are compared
// after JSON string decoding, so a name written through Unicode escapes is
// judged by the letters it decodes to: an escaped exact "entries" is the
// standard field, an escaped case variant is rejected.
func rejectEntriesCaseVariants(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		// Not an object; loadStrict's object check reports it.
		return nil
	}
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := tok.(string)
		if !ok {
			return fmt.Errorf("expected a field name, got %v", tok)
		}
		if key != "entries" && strings.EqualFold(key, "entries") {
			return fmt.Errorf("entries mapping must be spelled exactly %q; found %q", "entries", key)
		}
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return err
		}
	}
	return nil
}
```

