1	package vault
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	func TestPutGetAndVerify(t *testing.T) {
11		root := filepath.Join(t.TempDir(), "vault")
12		input := filepath.Join(t.TempDir(), "input.txt")
13		if err := os.WriteFile(input, []byte("release payload\n"), 0o644); err != nil {
14			t.Fatal(err)
15		}
16		store := New(root)
17		entry, err := store.Put("releases/app.txt", input)
18		if err != nil {
19			t.Fatal(err)
20		}
21		if entry.Size != 16 {
22			t.Fatalf("size=%d", entry.Size)
23		}
24		output := filepath.Join(t.TempDir(), "output.txt")
25		if err := store.Get(entry.Name, output); err != nil {
26			t.Fatal(err)
27		}
28		got, err := os.ReadFile(output)
29		if err != nil {
30			t.Fatal(err)
31		}
32		if string(got) != "release payload\n" {
33			t.Fatalf("content=%q", got)
34		}
35		if count, err := store.Verify(); err != nil || count != 1 {
36			t.Fatalf("count=%d err=%v", count, err)
37		}
38	}
39	
40	func TestRejectsEscapingName(t *testing.T) {
41		store := New(filepath.Join(t.TempDir(), "vault"))
42		if _, err := store.Put("../escape", "missing"); err == nil {
43			t.Fatal("expected invalid name error")
44		}
45	}
46	
47	// writeInput writes content to a fresh temp file and returns its path.
48	func writeInput(t *testing.T, content []byte) string {
49		t.Helper()
50		path := filepath.Join(t.TempDir(), "input.bin")
51		if err := os.WriteFile(path, content, 0o644); err != nil {
52			t.Fatal(err)
53		}
54		return path
55	}
56	
57	// objectPathOf returns the repository object path for content stored in root.
58	func objectPathOf(root string, content []byte) string {
59		return filepath.Join(root, "objects", digestOf(string(content)))
60	}
61	
62	// entriesOf loads the current name mapping.
63	func entriesOf(t *testing.T, store *Store) map[string]Entry {
64		t.Helper()
65		entries, err := store.List()
66		if err != nil {
67			t.Fatal(err)
68		}
69		idx := map[string]Entry{}
70		for _, entry := range entries {
71			idx[entry.Name] = entry
72		}
73		return idx
74	}
75	
76	// uploadTemps lists leftover staged-upload temp files in the objects dir.
77	func uploadTemps(t *testing.T, root string) []string {
78		t.Helper()
79		matches, err := filepath.Glob(filepath.Join(root, "objects", ".upload-*"))
80		if err != nil {
81			t.Fatal(err)
82		}
83		return matches
84	}
85	
86	func TestPutReusesHealthySharedObject(t *testing.T) {
87		root := filepath.Join(t.TempDir(), "vault")
88		store := New(root)
89		content := []byte("shared payload\n")
90		input := writeInput(t, content)
91	
92		first, err := store.Put("a/one.bin", input)
93		if err != nil {
94			t.Fatal(err)
95		}
96		object := objectPathOf(root, content)
97		// Distinctive permissions prove the reuse path neither rewrites nor
98		// re-permissions the existing object.
99		if err := os.Chmod(object, 0o640); err != nil {
100			t.Fatal(err)
101		}
102		before, err := os.Stat(object)
103		if err != nil {
104			t.Fatal(err)
105		}
106	
107		second, err := store.Put("b/two.bin", input)
108		if err != nil {
109			t.Fatal(err)
110		}
111		if second.Digest != first.Digest || second.Size != first.Size {
112			t.Fatalf("entries disagree: %+v vs %+v", first, second)
113		}
114		after, err := os.Stat(object)
115		if err != nil {
116			t.Fatal(err)
117		}
118		if after.Mode().Perm() != 0o640 {
119			t.Fatalf("object permissions changed to %v", after.Mode().Perm())
120		}
121		if !os.SameFile(before, after) {
122			t.Fatal("object was replaced instead of reused")
123		}
124		got, err := os.ReadFile(object)
125		if err != nil || string(got) != string(content) {
126			t.Fatalf("object content=%q err=%v", got, err)
127		}
128		entries := entriesOf(t, store)
129		if len(entries) != 2 || entries["a/one.bin"].Digest != first.Digest || entries["b/two.bin"].Digest != first.Digest {
130			t.Fatalf("entries=%v", entries)
131		}
132	}
133	
134	func TestPutEmptyFileReusesEmptyObject(t *testing.T) {
135		root := filepath.Join(t.TempDir(), "vault")
136		store := New(root)
137		input := writeInput(t, nil)
138		entry, err := store.Put("empty/one", input)
139		if err != nil {
140			t.Fatal(err)
141		}
142		if entry.Size != 0 {
143			t.Fatalf("size=%d", entry.Size)
144		}
145		if _, err := store.Put("empty/two", input); err != nil {
146			t.Fatal(err)
147		}
148		if len(entriesOf(t, store)) != 2 {
149			t.Fatalf("entries=%v", entriesOf(t, store))
150		}
151	}
152	
153	// expectReuseFailure corrupts or replaces the object for content, then
154	// confirms that re-uploading the healthy content fails, names the upload and
155	// digest, and leaves the mapping, the object, and the staging area untouched.
156	func expectReuseFailure(t *testing.T, root string, store *Store, content []byte, want string) {
157		t.Helper()
158		digest := digestOf(string(content))
159		input := writeInput(t, content)
160		before := entriesOf(t, store)
161	
162		_, err := store.Put("new/name.bin", input)
163		if err == nil {
164			t.Fatal("expected put to fail")
165		}
166		if !strings.Contains(err.Error(), "new/name.bin") || !strings.Contains(err.Error(), digest) {
167			t.Fatalf("error should name the upload and digest: %v", err)
168		}
169		if want != "" && !strings.Contains(err.Error(), want) {
170			t.Fatalf("error %v should mention %q", err, want)
171		}
172	
173		after := entriesOf(t, store)
174		if len(after) != len(before) {
175			t.Fatalf("mapping changed: %v -> %v", before, after)
176		}
177		for name, entry := range before {
178			if after[name] != entry {
179				t.Fatalf("entry %q changed: %+v -> %+v", name, entry, after[name])
180			}
181		}
182		if temps := uploadTemps(t, root); len(temps) != 0 {
183			t.Fatalf("staged upload left behind: %v", temps)
184		}
185	}
186	
187	func TestPutRejectsTruncatedExistingObject(t *testing.T) {
188		root := filepath.Join(t.TempDir(), "vault")
189		store := New(root)
190		content := []byte("full healthy payload\n")
191		if _, err := store.Put("old/name.bin", writeInput(t, content)); err != nil {
192			t.Fatal(err)
193		}
194		object := objectPathOf(root, content)
195		if err := os.Truncate(object, 4); err != nil {
196			t.Fatal(err)
197		}
198		expectReuseFailure(t, root, store, content, "bytes")
199		// The damaged object is left as it was; the upload must not repair it.
200		info, err := os.Stat(object)
201		if err != nil || info.Size() != 4 {
202			t.Fatalf("object size=%v err=%v", info.Size(), err)
203		}
204	}
205	
206	func TestPutRejectsSameSizeDifferentContentObject(t *testing.T) {
207		root := filepath.Join(t.TempDir(), "vault")
208		store := New(root)
209		content := []byte("original bytes here")
210		if _, err := store.Put("old/name.bin", writeInput(t, content)); err != nil {
211			t.Fatal(err)
212		}
213		object := objectPathOf(root, content)
214		if err := os.WriteFile(object, []byte("modified bytes here"), 0o644); err != nil {
215			t.Fatal(err)
216		}
217		expectReuseFailure(t, root, store, content, "checksum")
218	}
219	
220	func TestPutRejectsSymlinkObject(t *testing.T) {
221		for _, dangling := range []bool{false, true} {
222			root := filepath.Join(t.TempDir(), "vault")
223			store := New(root)
224			content := []byte("symlink target test\n")
225			if _, err := store.Put("old/name.bin", writeInput(t, content)); err != nil {
226				t.Fatal(err)
227			}
228			object := objectPathOf(root, content)
229			if err := os.Remove(object); err != nil {
230				t.Fatal(err)
231			}
232			target := writeInput(t, content) // healthy content at the link target
233			if dangling {
234				target = filepath.Join(t.TempDir(), "missing")
235			}
236			if err := os.Symlink(target, object); err != nil {
237				t.Fatal(err)
238			}
239			expectReuseFailure(t, root, store, content, "symbolic link")
240			// The link itself must survive; it is never replaced by the upload.
241			info, err := os.Lstat(object)
242			if err != nil || info.Mode()&os.ModeSymlink == 0 {
243				t.Fatalf("dangling=%v: object is no longer a symlink: %v", dangling, err)
244			}
245		}
246	}
247	
248	func TestPutRejectsDirectoryObject(t *testing.T) {
249		root := filepath.Join(t.TempDir(), "vault")
250		store := New(root)
251		content := []byte("directory collision\n")
252		if _, err := store.Put("old/name.bin", writeInput(t, content)); err != nil {
253			t.Fatal(err)
254		}
255		object := objectPathOf(root, content)
256		if err := os.Remove(object); err != nil {
257			t.Fatal(err)
258		}
259		if err := os.Mkdir(object, 0o755); err != nil {
260			t.Fatal(err)
261		}
262		expectReuseFailure(t, root, store, content, "not a regular file")
263	}
264	
265	func TestPutFailureKeepsExistingNameRecord(t *testing.T) {
266		root := filepath.Join(t.TempDir(), "vault")
267		store := New(root)
268		good := []byte("currently mapped content\n")
269		first, err := store.Put("shared/name.bin", writeInput(t, good))
270		if err != nil {
271			t.Fatal(err)
272		}
273		// Damage the object a second upload of the same name would reuse.
274		other := []byte("other content entirely\n")
275		if _, err := store.Put("other/name.bin", writeInput(t, other)); err != nil {
276			t.Fatal(err)
277		}
278		if err := os.Truncate(objectPathOf(root, other), 2); err != nil {
279			t.Fatal(err)
280		}
281		if _, err := store.Put("shared/name.bin", writeInput(t, other)); err == nil {
282			t.Fatal("expected put to fail")
283		}
284		entry := entriesOf(t, store)["shared/name.bin"]
285		if entry != first {
286			t.Fatalf("existing record replaced: %+v -> %+v", first, entry)
287		}
288	}
289	
290	func TestPutStoresNewObjectWhenDigestAbsent(t *testing.T) {
291		root := filepath.Join(t.TempDir(), "vault")
292		store := New(root)
293		content := []byte("fresh content\n")
294		entry, err := store.Put("new/name.bin", writeInput(t, content))
295		if err != nil {
296			t.Fatal(err)
297		}
298		got, err := os.ReadFile(objectPathOf(root, content))
299		if err != nil || string(got) != string(content) {
300			t.Fatalf("object content=%q err=%v", got, err)
301		}
302		if entry.Digest != digestOf(string(content)) || entry.Size != int64(len(content)) {
303			t.Fatalf("entry=%+v", entry)
304		}
305		if temps := uploadTemps(t, root); len(temps) != 0 {
306			t.Fatalf("staged upload left behind: %v", temps)
307		}
308	}
