14	// captureStdout runs fn with os.Stdout redirected to a temp file and returns
15	// everything it wrote.
16	func captureStdout(t *testing.T, fn func()) string {
17		t.Helper()
18		orig := os.Stdout
19		tmp, err := os.CreateTemp(t.TempDir(), "stdout-*")
20		if err != nil {
21			t.Fatal(err)
22		}
23		os.Stdout = tmp
24		defer func() { os.Stdout = orig }()
25		fn()
26		if err := tmp.Close(); err != nil {
27			t.Fatal(err)
28		}
29		data, err := os.ReadFile(tmp.Name())
30		if err != nil {
31			t.Fatal(err)
32		}
33		return string(data)
34	}
35	
36	// TestPutCLIRejectsCorruptIndexSilently applies the strict mapping
37	// precondition at the command line: a healthy put keeps its existing success
38	// line, but a put over a damaged index fails naming the upload and the index
39	// problem, prints no stored success line, and leaves the mapping and objects
40	// untouched.
41	func TestPutCLIRejectsCorruptIndexSilently(t *testing.T) {
42		root := filepath.Join(t.TempDir(), "vault")
43		input := filepath.Join(t.TempDir(), "a.txt")
44		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
45			t.Fatal(err)
46		}
47		if err := run([]string{"init", "--root", root}); err != nil {
48			t.Fatal(err)
49		}
50	
51		out := captureStdout(t, func() {
52			if err := run([]string{"put", "--root", root, "--name", "keep.txt", "--file", input}); err != nil {
53				t.Fatal(err)
54			}
55		})
56		if !strings.Contains(out, "stored keep.txt ") {
57			t.Fatalf("a healthy put must keep its existing success line, got %q", out)
58		}
59	
60		indexPath := filepath.Join(root, "index.json")
61		indexBefore, err := os.ReadFile(indexPath)
62		if err != nil {
63			t.Fatal(err)
64		}
65		// Duplicate artifact key: corruption, never a mapping to overwrite.
66		corrupt := []byte(`{"entries":{` +
67			`"keep.txt":{"name":"keep.txt","digest":"` + strings.Repeat("a", 64) + `","size":7,"createdAt":"2026-01-01T00:00:00Z"},` +
68			`"keep.txt":{"name":"keep.txt","digest":"` + strings.Repeat("a", 64) + `","size":7,"createdAt":"2026-01-01T00:00:00Z"}` +
69			`}}`)
70		if err := os.WriteFile(indexPath, corrupt, 0o644); err != nil {
71			t.Fatal(err)
72		}
73	
74		var putErr error
75		out = captureStdout(t, func() {
76			putErr = run([]string{"put", "--root", root, "--name", "new.txt", "--file", input})
77		})
78		if putErr == nil {
79			t.Fatal("expected put over a corrupt index to fail")
80		}
81		if !strings.Contains(putErr.Error(), `cannot store "new.txt"`) {
82			t.Fatalf("error %q does not name the upload", putErr)
83		}
84		if !strings.Contains(putErr.Error(), "current index is corrupt") ||
85			!strings.Contains(putErr.Error(), `duplicate key "keep.txt"`) {
86			t.Fatalf("error %q does not name the corrupt index and duplicated key", putErr)
87		}
88		if out != "" {
89			t.Fatalf("failed put must print no stored success line, got %q", out)
90		}
91	
92		indexAfter, err := os.ReadFile(indexPath)
93		if err != nil {
94			t.Fatal(err)
95		}
96		if string(indexAfter) != string(corrupt) {
97			t.Fatalf("corrupt index was rewritten\nwas: %s\nnow: %s", corrupt, indexAfter)
98		}
99		if string(indexAfter) == string(indexBefore) {
100			t.Fatal("test setup did not damage the index")
101		}
102	}
103	
104	// TestListCLIStrictMapping applies the strict mapping precondition at the
105	// command line: a healthy repository prints one name<TAB>digest<TAB>size line
106	// per artifact sorted by full name (zero rows for a genuine empty mapping),
107	// while a damaged index fails with an error, prints no artifact rows at all,
108	// and leaves the index bytes untouched; a repository that was never
109	// initialized is reported instead of listed as empty.
110	func TestListCLIStrictMapping(t *testing.T) {
111		root := filepath.Join(t.TempDir(), "vault")
112	
113		// A repository that was never initialized is an error, not an empty list.
114		var listErr error
115		out := captureStdout(t, func() {
116			listErr = run([]string{"list", "--root", root})
117		})
118		if listErr == nil {
119			t.Fatal("expected list of an uninitialized repository to fail")
120		}
121		if !strings.Contains(listErr.Error(), "not initialized") {
122			t.Fatalf("error %q does not report the repository as uninitialized", listErr)
123		}
124		if out != "" {
125			t.Fatalf("uninitialized repository printed rows: %q", out)
126		}
127	
128		if err := run([]string{"init", "--root", root}); err != nil {
129			t.Fatal(err)
130		}
131		// A genuine {"entries":{}} lists successfully with no rows.
132		out = captureStdout(t, func() {
133			if err := run([]string{"list", "--root", root}); err != nil {
134				t.Fatal(err)
135			}
136		})
137		if out != "" {
138			t.Fatalf("empty mapping printed rows: %q", out)
139		}
140	
141		in := filepath.Join(t.TempDir(), "a.txt")
142		if err := os.WriteFile(in, []byte("payload"), 0o644); err != nil {
143			t.Fatal(err)
144		}
145		if err := run([]string{"put", "--root", root, "--name", "z/up.bin", "--file", in}); err != nil {
146			t.Fatal(err)
147		}
148		empty := filepath.Join(t.TempDir(), "empty.bin")
149		if err := os.WriteFile(empty, nil, 0o644); err != nil {
150			t.Fatal(err)
151		}
152		if err := run([]string{"put", "--root", root, "--name", "a/down.bin", "--file", empty}); err != nil {
153			t.Fatal(err)
154		}
155		out = captureStdout(t, func() {
156			if err := run([]string{"list", "--root", root}); err != nil {
157				t.Fatal(err)
158			}
159		})
160		lines := strings.Split(strings.TrimSuffix(out, "\n"), "\n")
161		if len(lines) != 2 {
162			t.Fatalf("expected two rows, got %q", out)
163		}
164		if !strings.HasPrefix(lines[0], "a/down.bin\t") ||
165			!strings.HasSuffix(lines[0], "\t0") {
166			t.Fatalf("zero-byte row not first and tab-formatted: %q", lines[0])
167		}
168		if !strings.HasPrefix(lines[1], "z/up.bin\t") {
169			t.Fatalf("second row not the multi-level name: %q", lines[1])
170		}
171	
172		// Damage the mapping with a duplicate artifact name: the whole command
173		// fails and not a single row reaches stdout.
174		indexPath := filepath.Join(root, "index.json")
175		corrupt := []byte(`{"entries":{` +
176			`"z/up.bin":{"name":"z/up.bin","digest":"` + strings.Repeat("a", 64) + `","size":7,"createdAt":"2026-01-01T00:00:00Z"},` +
177			`"z/up.bin":{"name":"z/up.bin","digest":"` + strings.Repeat("a", 64) + `","size":7,"createdAt":"2026-01-01T00:00:00Z"}` +
178			`}}`)
179		if err := os.WriteFile(indexPath, corrupt, 0o644); err != nil {
180			t.Fatal(err)
181		}
182		out = captureStdout(t, func() {
183			listErr = run([]string{"list", "--root", root})
184		})
185		if listErr == nil {
186			t.Fatal("expected list over a corrupt index to fail")
187		}
188		if !strings.Contains(listErr.Error(), "current index is corrupt") ||
189			!strings.Contains(listErr.Error(), `duplicate key "z/up.bin"`) {
190			t.Fatalf("error %q does not name the corrupt index and duplicated key", listErr)
191		}
192		if out != "" {
193			t.Fatalf("failed list must print no artifact rows, got %q", out)
194		}
195		after, err := os.ReadFile(indexPath)
196		if err != nil {
197			t.Fatal(err)
198		}
199		if string(after) != string(corrupt) {
200			t.Fatalf("corrupt index was rewritten\nwas: %s\nnow: %s", corrupt, after)
201		}
202	}
203	
204	// TestSnapshotCreateCLIRejectsCorruptIndex applies the same rules at the
205	// command line as the Go API: a healthy create keeps its existing success
206	// line, while an unusable current mapping fails with an error naming the
207	// snapshot and the index, prints no success line, and leaves no snapshot.
208	func TestSnapshotCreateCLIRejectsCorruptIndex(t *testing.T) {
209		root := filepath.Join(t.TempDir(), "vault")
210		input := filepath.Join(t.TempDir(), "a.txt")
211		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
212			t.Fatal(err)
213		}
214		if err := run([]string{"init", "--root", root}); err != nil {
215			t.Fatal(err)
216		}
217		if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
218			t.Fatal(err)
219		}
220	
221		out := captureStdout(t, func() {
222			if err := run([]string{"snapshot", "create", "--root", root, "--name", "good"}); err != nil {
223				t.Fatal(err)
224			}
225		})
226		if !strings.Contains(out, "snapshot good created with 1 entries") {
227			t.Fatalf("successful create must keep its existing success line, got %q", out)
228		}
229	
230		// A null entries mapping is corruption, never an empty snapshot.
231		if err := os.WriteFile(filepath.Join(root, "index.json"),
232			[]byte(`{"entries":null}`), 0o644); err != nil {
233			t.Fatal(err)
234		}
235		var createErr error
236		out = captureStdout(t, func() {
237			createErr = run([]string{"snapshot", "create", "--root", root, "--name", "bad"})
238		})
239		if createErr == nil {
240			t.Fatal("expected create over a corrupt index to fail")
241		}
242		if !strings.Contains(createErr.Error(), `cannot create snapshot "bad"`) {
243			t.Fatalf("error %q does not name the snapshot being created", createErr)
244		}
245		if !strings.Contains(createErr.Error(), "missing entries mapping") {
246			t.Fatalf("error %q does not say why the index is unusable", createErr)
247		}
248		if out != "" {
249			t.Fatalf("failed create must print nothing, got %q", out)
250		}
251	
252		listOut := captureStdout(t, func() {
253			if err := run([]string{"snapshot", "list", "--root", root}); err != nil {
254				t.Fatal(err)
255			}
256		})
257		if !strings.Contains(listOut, "good\t1\n") || strings.Contains(listOut, "bad") {
258			t.Fatalf("failed create left a snapshot behind: %q", listOut)
259		}
260	}
261	
262	// TestSnapshotRestoreCLI confirms the command-line entry point follows the
263	// same restore rules as the Go API: a damaged record fails (the caller exits
264	// non-zero and no success line is printed), while a healthy record restores
265	// and prints the success line.
266	func TestSnapshotRestoreCLI(t *testing.T) {
267		root := filepath.Join(t.TempDir(), "vault")
268		input := filepath.Join(t.TempDir(), "a.txt")
269		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
270			t.Fatal(err)
271		}
272	
273		if err := run([]string{"init", "--root", root}); err != nil {
274			t.Fatal(err)
275		}
276		if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
277			t.Fatal(err)
278		}
279		if err := run([]string{"snapshot", "create", "--root", root, "--name", "s"}); err != nil {
280			t.Fatal(err)
281		}
282		if err := os.WriteFile(input, []byte("changed payload"), 0o644); err != nil {
283			t.Fatal(err)
284		}
285		if err := run([]string{"put", "--root", root, "--name", "b.txt", "--file", input}); err != nil {
286			t.Fatal(err)
287		}
288	
289		// Damage the record: null entries must not be treated as an empty snapshot.
290		if err := os.WriteFile(filepath.Join(root, "snapshots", "s.json"),
291			[]byte(`{"name":"s","entries":null}`), 0o644); err != nil {
292			t.Fatal(err)
293		}
294	
295		var restoreErr error
296		out := captureStdout(t, func() {
297			restoreErr = run([]string{"snapshot", "restore", "--root", root, "--name", "s"})
298		})
299		if restoreErr == nil {
300			t.Fatal("expected CLI restore of a damaged record to fail")
301		}
302		if !strings.Contains(restoreErr.Error(), `snapshot "s" is corrupted`) {
303			t.Fatalf("error %q does not identify the damaged snapshot", restoreErr)
304		}
305		if strings.Contains(out, "restored snapshot") {
306			t.Fatalf("damaged restore printed a success line: %q", out)
307		}
308	
309		// The current mapping is intact: both artifacts remain listed.
310		listOut := captureStdout(t, func() {
311			if err := run([]string{"list", "--root", root}); err != nil {
312				t.Fatal(err)
313			}
314		})
315		if !strings.Contains(listOut, "a.txt") || !strings.Contains(listOut, "b.txt") {
316			t.Fatalf("mapping changed after failed CLI restore: %q", listOut)
317		}
318	
319		// Repair the record through the API-identical CLI path and restore. The
320		// freshly created snapshot captures the current two-artifact mapping.
321		if err := os.Remove(filepath.Join(root, "snapshots", "s.json")); err != nil {
322			t.Fatal(err)
323		}
324		if err := run([]string{"snapshot", "create", "--root", root, "--name", "s2"}); err != nil {
325			t.Fatal(err)
326		}
327		out = captureStdout(t, func() {
328			restoreErr = run([]string{"snapshot", "restore", "--root", root, "--name", "s2"})
329		})
330		if restoreErr != nil {
331			t.Fatal(restoreErr)
332		}
333		if !strings.Contains(out, "restored snapshot s2") {
334			t.Fatalf("successful CLI restore did not print the success line: %q", out)
335		}
336	}
337	
338	// TestSnapshotListCLIAtomicOnCorruption confirms the command line applies
339	// the same rules as the Go API: healthy snapshots print one
340	// "name<TAB>count" line sorted by their full name, but a damaged record
341	// aborts the whole command with no prior snapshot lines on stdout.
342	func TestSnapshotListCLIAtomicOnCorruption(t *testing.T) {
343		root := filepath.Join(t.TempDir(), "vault")
344		if err := run([]string{"init", "--root", root}); err != nil {
345			t.Fatal(err)
346		}
347		input := filepath.Join(t.TempDir(), "a.txt")
348		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
349			t.Fatal(err)
350		}
351		if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
352			t.Fatal(err)
353		}
354		for _, name := range []string{"releases/stable", "zeta", "alpha"} {
355			if err := run([]string{"snapshot", "create", "--root", root, "--name", name}); err != nil {
356				t.Fatal(err)
357			}
358		}
359	
360		out := captureStdout(t, func() {
361			if err := run([]string{"snapshot", "list", "--root", root}); err != nil {
362				t.Fatal(err)
363			}
364		})
365		want := "alpha\t1\nreleases/stable\t1\nzeta\t1\n"
366		if out != want {
367			t.Fatalf("list output=%q, want %q", out, want)
368		}
369	
370		// A healthy explicit empty-entries snapshot lists with zero entries.
371		if err := run([]string{"snapshot", "create", "--root", root, "--name", "empty"}); err != nil {
372			t.Fatal(err)
373		}
374		if err := os.WriteFile(filepath.Join(root, "snapshots", "empty.json"),
375			[]byte(`{"name":"empty","entries":{}}`), 0o644); err != nil {
376			t.Fatal(err)
377		}
378		out = captureStdout(t, func() {
379			if err := run([]string{"snapshot", "list", "--root", root}); err != nil {
380				t.Fatal(err)
381			}
382		})
383		if !strings.Contains(out, "empty\t0\n") {
384			t.Fatalf("empty snapshot not listed with zero entries: %q", out)
385		}
386	
387		// Damage one record: the command must fail and print nothing at all, even
388		// though three healthy snapshots were read alongside it.
389		if err := os.WriteFile(filepath.Join(root, "snapshots", "zeta.json"),
390			[]byte(`{"name":"zeta"}`), 0o644); err != nil {
391			t.Fatal(err)
392		}
393		var listErr error
394		out = captureStdout(t, func() {
395			listErr = run([]string{"snapshot", "list", "--root", root})
396		})
397		if listErr == nil {
398			t.Fatal("expected list with a damaged record to fail")
399		}
400		if !strings.Contains(listErr.Error(), `snapshot "zeta" is corrupted`) {
401			t.Fatalf("error %q does not identify the damaged snapshot", listErr)
402		}
403		if out != "" {
404			t.Fatalf("a failed list must leave no snapshot lines on stdout, got %q", out)
405		}
406	
407		// A repository that has never held a snapshot succeeds with empty output.
408		fresh := filepath.Join(t.TempDir(), "vault")
409		if err := run([]string{"init", "--root", fresh}); err != nil {
410			t.Fatal(err)
411		}
412		out = captureStdout(t, func() {
413			if err := run([]string{"snapshot", "list", "--root", fresh}); err != nil {
414				t.Fatal(err)
415			}
416		})
417		if out != "" {
418			t.Fatalf("fresh repository listed output: %q", out)
419		}
420	}
421	
422	// TestSnapshotImportCLIRejectsRecordSizeMismatch confirms the command line
423	// fails (non-zero error, no "imported" success line) when a package's target
424	// record sizes an artifact differently from the carried content, and that no
425	// content object or snapshot is left behind in the destination.
426	func TestSnapshotImportCLIRejectsRecordSizeMismatch(t *testing.T) {
427		src := filepath.Join(t.TempDir(), "vault")
428		in := filepath.Join(t.TempDir(), "a.txt")
429		const content = "abcdefg" // 7 bytes
430		if err := os.WriteFile(in, []byte(content), 0o644); err != nil {
431			t.Fatal(err)
432		}
433		if err := run([]string{"init", "--root", src}); err != nil {
434			t.Fatal(err)
435		}
436		if err := run([]string{"put", "--root", src, "--name", "a.txt", "--file", in}); err != nil {
437			t.Fatal(err)
438		}
439		if err := run([]string{"snapshot", "create", "--root", src, "--name", "s"}); err != nil {
440			t.Fatal(err)
441		}
442		pkg := filepath.Join(t.TempDir(), "s.pkg")
443		if err := run([]string{"snapshot", "export", "--root", src, "--name", "s", "--output", pkg}); err != nil {
444			t.Fatal(err)
445		}
446	
447		// Corrupt only the snapshot record's size (8) while the carried object
448		// honestly stays 7 bytes. The entry is the unique size field followed by a
449		// createdAt, distinct from the object record's size/data pair.
450		raw, err := os.ReadFile(pkg)
451		if err != nil {
452			t.Fatal(err)
453		}
454		sum := sha256.Sum256([]byte(content))
455		digest := hex.EncodeToString(sum[:])
456		got := string(raw)
457		// The entry size is the one followed by createdAt (the object record's is
458		// followed by data), so the rewrite hits only the snapshot record.
459		entrySize := regexp.MustCompile(`("size": )7(,\s+"createdAt")`)
460		objectSize := regexp.MustCompile(`("size": )7(,\s+"data":)`)
461		if entrySize.FindString(got) == "" {
462			t.Fatalf("test package did not contain the expected entry record: %s", got)
463		}
464		got = entrySize.ReplaceAllString(got, `${1}8${2}`)
465		if err := os.WriteFile(pkg, []byte(got), 0o644); err != nil {
466			t.Fatal(err)
467		}
468		// The carried object record stays truthful (7 bytes + matching base64), so
469		// the failure is a record-size mismatch rather than bad content.
470		if objectSize.FindString(got) == "" ||
471			!strings.Contains(got, `"data": "`+base64.StdEncoding.EncodeToString([]byte(content))+`"`) {
472			t.Fatal("test setup damaged the object record instead of the snapshot entry")
473		}
474	
475		dst := filepath.Join(t.TempDir(), "vault")
476		if err := run([]string{"init", "--root", dst}); err != nil {
477			t.Fatal(err)
478		}
479		var importErr error
480		out := captureStdout(t, func() {
481			importErr = run([]string{"snapshot", "import", "--root", dst, "--file", pkg})
482		})
483		if importErr == nil {
484			t.Fatal("expected import of a mis-sized record to fail")
485		}
486		msg := importErr.Error()
487		for _, want := range []string{`snapshot "s"`, "a.txt", digest, "8", "7"} {
488			if !strings.Contains(msg, want) {
489				t.Fatalf("error %q does not report %q", msg, want)
490			}
491		}
492		if strings.Contains(out, "imported snapshot") {
493			t.Fatalf("failed import printed a success line: %q", out)
494		}
495	
496		// No snapshot and no content object may remain.
497		listOut := captureStdout(t, func() {
498			if err := run([]string{"snapshot", "list", "--root", dst}); err != nil {
499				t.Fatal(err)
500			}
501		})
502		if listOut != "" {
503			t.Fatalf("snapshot left behind: %q", listOut)
504		}
505		if entries, err := os.ReadDir(filepath.Join(dst, "objects")); err != nil {
506			t.Fatal(err)
507		} else {
508			for _, ent := range entries {
509				if !strings.HasPrefix(ent.Name(), ".") {
510					t.Fatalf("content object left behind after failed import: %s", ent.Name())
511				}
512			}
513		}
514	}
515	
516	// TestSnapshotRestoreCLIMissingName fails without a success line when the
517	// snapshot does not exist, distinguishing "not found" from corruption.
518	func TestSnapshotRestoreCLIMissingName(t *testing.T) {
519		root := filepath.Join(t.TempDir(), "vault")
520		if err := run([]string{"init", "--root", root}); err != nil {
521			t.Fatal(err)
522		}
523		var restoreErr error
524		out := captureStdout(t, func() {
525			restoreErr = run([]string{"snapshot", "restore", "--root", root, "--name", "absent"})
526		})
527		if restoreErr == nil {
528			t.Fatal("expected restore of a missing snapshot to fail")
529		}
530		if !strings.Contains(restoreErr.Error(), `snapshot "absent" not found`) {
531			t.Fatalf("error %q is not a not-found error", restoreErr)
532		}
533		if strings.Contains(out, "restored snapshot") {
534			t.Fatalf("missing-snapshot restore printed a success line: %q", out)
535		}
536	}
